// 电机引脚定义
#define MOTOR_LEFT_IN1   GPIO_PIN_5
#define MOTOR_LEFT_IN2   GPIO_PIN_6
#define MOTOR_RIGHT_IN1  GPIO_PIN_7
#define MOTOR_RIGHT_IN2  GPIO_PIN_8
#define MOTOR_PORT       GPIOB

// 设置速度(0-100)
void setSpeed(uint8_t speed) {
    uint16_t ccr = speed * 10;  // 0-1000
    __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, ccr);
    __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_2, ccr);
}

// 前进
void moveForward(void) {
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_LEFT_IN1, GPIO_PIN_SET);
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_LEFT_IN2, GPIO_PIN_RESET);
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_RIGHT_IN1, GPIO_PIN_SET);
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_RIGHT_IN2, GPIO_PIN_RESET);
}

// 左转(差速)
void turnLeft(void) {
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_LEFT_IN1, GPIO_PIN_RESET);
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_LEFT_IN2, GPIO_PIN_RESET);
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_RIGHT_IN1, GPIO_PIN_SET);
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_RIGHT_IN2, GPIO_PIN_RESET);
}

// 停止
void motorStop(void) {
    HAL_GPIO_WritePin(MOTOR_PORT, MOTOR_LEFT_IN1| MOTOR_LEFT_IN2|
                      MOTOR_RIGHT_IN1|MOTOR_RIGHT_IN2, GPIO_PIN_RESET);
}

#define IR_LEFT  GPIO_PIN_11
#define IR_RIGHT GPIO_PIN_12
#define IR_PORT  GPIOA

void avoidTask(void* arg) {
    while (1) {
        uint8_t left  = HAL_GPIO_ReadPin(IR_PORT, IR_LEFT)  == GPIO_PIN_RESET;
        uint8_t right = HAL_GPIO_ReadPin(IR_PORT, IR_RIGHT) == GPIO_PIN_RESET;

        if (!left && !right) {
            moveForward();  // 无障碍前进
        } else if (left && !right) {
            turnRight();    // 左有障碍，右转
            vTaskDelay(500);
        } else if (!left && right) {
            turnLeft();     // 右有障碍，左转
            vTaskDelay(500);
        } else {
            moveBackward(); // 都有障碍，后退
            vTaskDelay(300);
            turnRight();    // 转向
            vTaskDelay(500);
        }
        vTaskDelay(50);  // 检测周期
    }
}

uint8_t btCmd;
SemaphoreHandle_t btSem;
uint8_t mode = 0;  // 0:避障 1:蓝牙

void HAL_UART_RxCpltCallback(UART_HandleTypeDef* huart) {
    if (huart->Instance == USART2) {
        BaseType_t xWoken = pdFALSE;
        xSemaphoreGiveFromISR(btSem, &xWoken);
        portYIELD_FROM_ISR(xWoken);
        HAL_UART_Receive_IT(&huart2, &btCmd, 1);
    }
}

void btControlTask(void* arg) {
    while (1) {
        xSemaphoreTake(btSem, portMAX_DELAY);
        if (mode == 1) {  // 蓝牙模式
            switch (btCmd) {
                case 'F': moveForward(); break;
                case 'B': moveBackward(); break;
                case 'L': turnLeft(); vTaskDelay(300); motorStop(); break;
                case 'R': turnRight(); vTaskDelay(300); motorStop(); break;
                case 'S': motorStop(); break;
                case '0': setSpeed(0); break;
                case '9': setSpeed(90); break;
            }
        }
    }
}

// 完整小车系统
SemaphoreHandle_t btSem;
SemaphoreHandle_t modeMutex;
uint8_t mode = 0;
uint8_t currentSpeed = 50;

void avoidTask(void* arg) {
    while (1) {
        xSemaphoreTake(modeMutex, portMAX_DELAY);
        uint8_t m = mode;
        xSemaphoreGive(modeMutex);
        if (m == 0) {  // 避障模式
            // 避障逻辑...
        }
        vTaskDelay(50);
    }
}

void btTask(void* arg) {
    while (1) {
        xSemaphoreTake(btSem, portMAX_DELAY);
        xSemaphoreTake(modeMutex, portMAX_DELAY);
        uint8_t m = mode;
        xSemaphoreGive(modeMutex);
        if (m == 1) {  // 蓝牙模式
            // 蓝牙命令处理...
        }
    }
}

void HAL_GPIO_EXTI_Callback(uint16_t pin) {
    if (pin == GPIO_PIN_0) {  // 按键
        xSemaphoreTake(modeMutex, portMAX_DELAY);
        mode = !mode;
        xSemaphoreGive(modeMutex);
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_TIM2_Init();  // PWM
    MX_USART2_Init();  // 蓝牙
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_2);
    HAL_UART_Receive_IT(&huart2, &btCmd, 1);

    btSem = xSemaphoreCreateBinary();
    modeMutex = xSemaphoreCreateMutex();

    xTaskCreate(avoidTask, "Avoid", 256, NULL, 4, NULL);
    xTaskCreate(btTask, "BT", 256, NULL, 3, NULL);

    vTaskStartScheduler();
}
